package com.findit.servlet;
import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/report") public class ReportServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{if(!auth(q,p))return;try{q.setAttribute("categories",new ItemDAO().categories());q.getRequestDispatcher("/WEB-INF/views/report.jsp").forward(q,p);}catch(SQLException e){throw new ServletException(e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{if(!auth(q,p))return;q.setCharacterEncoding("UTF-8");String type=q.getParameter("reportType"),name=trim(q.getParameter("itemName")),loc=trim(q.getParameter("location")),date=q.getParameter("itemDate");try{int cat=Integer.parseInt(q.getParameter("categoryId"));if(!("LOST".equals(type)||"FOUND".equals(type))||name.isEmpty()||loc.isEmpty()||date==null)throw new IllegalArgumentException();Date d=Date.valueOf(date);new ItemDAO().create(((Number)q.getSession().getAttribute("userId")).intValue(),cat,type,name,trim(q.getParameter("description")),trim(q.getParameter("color")),loc,d);p.sendRedirect(q.getContextPath()+"/items?posted=1");}catch(Exception e){q.setAttribute("error","Please complete the required fields with valid values.");doGet(q,p);}}private boolean auth(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return false;}return true;}private String trim(String s){return s==null?"":s.trim();}}
